import math

def calculate_interval(k):
    # I_k = [ ln(k)/k, ln(k+1)/k )
    lower = math.log(k) / k
    upper = math.log(k + 1) / k
    return (lower, upper)

intervals = {}
for k in range(1, 6):
    intervals[k] = calculate_interval(k)

print("--- Intervals I_k ---")
for k, interval in intervals.items():
    print(f"I_{k}: [{interval[0]:.6f}, {interval[1]:.6f})")
